/**
 *  A test script for the Xoshiro128 implementation.
 *
 *  The reference values were generated by an independent implementation
 *  ported from the original C source of xoshiro128**.
 *
 *  @author     Paweł Kuźnik <pawel.kuznik@gmail.com>
 */

// the testing method
const expect = require('chai').expect;

// get the dependencies
const { Xoshiro128 } = require('../build/index.js');

const sequence = (generator, length) => Array.from({ length }, () => generator.next());

describe('Xoshiro128', () => {

    describe('reference values', () => {

        it('should match the reference for state [1, 2, 3, 4]', () => {

            expect(sequence(Xoshiro128.fromState([1, 2, 3, 4]), 8)).to.deep.equal([11520, 0, 5927040, 70819200, 2031721883, 1637235492, 1287239034, 3734860849]);
        });

        it('should match the reference for a state with all bits set', () => {

            const max = 0xffffffff;
            expect(sequence(Xoshiro128.fromState([max, max, max, max]), 8)).to.deep.equal([4294962679, 4294962679, 4292019319, 2943360, 1509943680, 246671744, 2681405836, 4051244843]);
        });

        it('should match the reference for seed 42', () => {

            expect(new Xoshiro128(42).state).to.deep.equal([551831576, 144025891, 322543647, 3034809370]);
            expect(sequence(new Xoshiro128(42), 5)).to.deep.equal([660444221, 3652823732, 77672526, 910233633, 2297337756]);
        });
    });

    describe('.state', () => {

        it('should restore the sequence from a saved state', () => {

            const generator = new Xoshiro128(1234);
            sequence(generator, 100);

            const restored = Xoshiro128.fromState(generator.state);
            expect(sequence(restored, 10)).to.deep.equal(sequence(generator, 10));
        });

        it('should return a copy of the state', () => {

            const generator = new Xoshiro128(1234);
            const state = generator.state;

            generator.next();
            expect(generator.state).to.not.deep.equal(state);
        });

        it('should reject a state of the wrong length', () => {

            expect(() => Xoshiro128.fromState([1, 2, 3])).to.throw();
        });

        it('should reject an all-zero state', () => {

            expect(() => Xoshiro128.fromState([0, 0, 0, 0])).to.throw();
        });
    });

    describe('.next()', () => {

        it('should generate unsigned 32-bit integers', () => {

            const generator = new Xoshiro128(7);

            for (let i = 0; i < 1000; i++) {

                const value = generator.next();
                expect(Number.isInteger(value)).to.equal(true);
                expect(value).to.be.at.least(0).and.below(2 ** 32);
            }
        });

        it('should give unrelated sequences for adjacent seeds', () => {

            const a = sequence(new Xoshiro128(1), 10);
            const b = sequence(new Xoshiro128(2), 10);

            a.forEach((value, index) => expect(value).to.not.equal(b[index]));
        });

        it('should pick different random seeds when unseeded', () => {

            expect(sequence(new Xoshiro128(), 10)).to.not.deep.equal(sequence(new Xoshiro128(), 10));
        });

        it('should generate numbers fast', () => {

            const generator = new Xoshiro128();

            for (let i = 0; i < 10000; i++) generator.next();
        }).timeout(10);
    });

    describe('.random()', () => {

        it('should spread evenly across [0, 1)', () => {

            const generator = new Xoshiro128(7);
            const buckets = new Array(10).fill(0);

            for (let i = 0; i < 100000; i++) buckets[Math.floor(generator.random() * 10)]++;

            // each bucket expects 10000 hits; 5 standard deviations is about 475
            for (const count of buckets) expect(count).to.be.within(9500, 10500);
        });
    });
});
